/**
 * Small shared process runner for package-level maintenance commands.
 *
 * The wrappers in this directory use it to keep package.json readable while preserving inherited output and exit
 * codes. Commands run serially because later checks consume artifacts generated by earlier checks.
 */

import { spawn } from "node:child_process";

export function packageManagerCommand() {
    return process.platform === "win32" ? "pnpm.exe" : "pnpm";
}

export function runCommand(command, args) {
    return new Promise((resolve, reject) => {
        const child = spawn(command, args, { stdio: "inherit" });

        child.once("error", reject);
        child.once("close", (code, signal) => {
            if (code === 0) resolve();
            else reject(new Error(`${args.join(" ")} ended with ${signal ?? `exit code ${code}`}`));
        });
    });
}

export async function runPackageScripts(scriptNames) {
    const packageManager = packageManagerCommand();

    for (const scriptName of scriptNames) {
        await runCommand(packageManager, ["run", scriptName]);
    }
}
